4	`timescale 1ns/1ps
5	`include "defines.sv"
6	// -------------------------------------------------------------------
7	module filt_cici_tb;
8	  time CLK_PERIOD = 400;
9	  //time F_CLK_PERIOD = CLK_PERIOD/`P_INTERPOLATION;
10	  
11	  reg       i_rst_an;
12	  reg       i_ena=1'b0;
13	  reg       i_clk=1'b0;
14	  reg       i_fclk=1'b0;
15	  reg       f_clk=1'b0;
16	  reg       s_clk;
17	  int       r_cnt=`P_INTERPOLATION;
18	  
19	  reg [`P_INP_DATA_W-1:0] i_data,r_data;
20	  wire                 rdy;
21	  wire signed [`P_OUP_DATA_W-1:0] oup_data;
22	  reg                             data_ready=1'b0;
23	  integer error_count=0;
24	  reg [8*64:1]                    filename_vcd;
25	  // READ-IN MATLAB STIMULI FILE  
26	  reg [8*64:1]                    filename_mat_inp;
27	  integer                         fid_mat_inp;
28	  integer                         status_mat_inp;  
29	  // READ-IN MATLAB RESPONSE FILE
30	  reg [8*64:1]                    filename_mat_oup;
31	  integer                         fid_mat_oup;
32	  integer                         status_mat_oup;
33	  reg signed [`P_OUP_DATA_W-1:0]  o_data_mat;
34	// -------------------------------------------------------------------    
35	  initial
36	    begin: RST
37	                        i_rst_an = 1'b1;
38	      #2                i_rst_an = 1'b0;
39	      #(0.5*CLK_PERIOD) i_rst_an = 1'b1;
40	    end
41	
42	  always @(posedge s_clk) 
43	    begin: EGU
44	      if (i_rst_an)
45	      i_ena = 1'b1;
46	    end
47	  
48	  always f_clk = #(CLK_PERIOD/(`P_INTERPOLATION*2)) ~f_clk;
49	  
50	  always @(posedge f_clk)
51	    begin: SCLK
52	      if (r_cnt<`P_INTERPOLATION-1)
53	        r_cnt <= r_cnt + 1;
54	      else
55	        r_cnt <= 'd0;
56	    end
57	  assign s_clk = (r_cnt<`P_INTERPOLATION/2) ? 1'b1 : 1'b0;   
58	 
59	 initial begin
60	    fork
61	        forever #2 i_fclk = f_clk;
62	        forever #2 i_clk = s_clk;
63	    join 
64	 end
65	
66	  initial
67	    begin: TEXTIO_READ_IN
68	      $display("### INFO: RTL Simulation of CIC Interpolation Filter.");
69	      $display("### Testcase %d", `TESTCASE);
70	      $sformat(filename_mat_inp,"%s%0d%s","./sim/testcases/stimuli/stimuli_tc_",`TESTCASE,"_mat.dat");
71	      $sformat(filename_mat_oup,"%s%0d%s","./sim/testcases/response/response_tc_",`TESTCASE,"_mat.dat");
72	      $display("%s",filename_mat_inp);
73	      fid_mat_inp = $fopen(filename_mat_inp, "r");
74	      fid_mat_oup = $fopen(filename_mat_oup, "r");
75	      if ((fid_mat_inp == `NULL)||(fid_mat_oup == `NULL)) begin
76	        $display("data_file handle was NULL");
77	        $finish;
78	      end
79	      
80	      @(posedge data_ready) 
81	        begin 
82		  $fclose(fid_mat_inp); 
83		  $fclose(fid_mat_oup); 
84	
85		  if (error_count>0)
86	            $display("### INFO: Testcase FAILED");
87	          else
88	            $display("### INFO: Testcase PASSED");
89		    
90	  	  $finish; 
91		end
92	    end
93	    
94	  always @(posedge i_clk)
95	    begin: MATLAB_STIMULI
96	      if (i_rst_an && i_ena)
97	        status_mat_inp = $fscanf(fid_mat_inp,"%d\n", i_data);
98	      else
99	        i_data = 'd0;
100		
101	      if ($feof(fid_mat_inp)) begin
102	        data_ready = 1'b1;
103	      end
104	    end
105	  
106	  always @(posedge i_fclk)
107	    begin: MATLAB_RESPONSE
108	      if (i_rst_an && i_ena)
109	        status_mat_oup = $fscanf(fid_mat_oup,"%d\n", o_data_mat);
110	    end
111	
112	  always @(negedge f_clk)
113	    begin
114	      if (i_rst_an && i_ena)
115	        if (oup_data != o_data_mat)
116		  begin 
117		    $error("### RTL = %d, MAT = %d", oup_data, o_data_mat); error_count<= error_count + 1;
118		  end
119	    end
120	      
121	  filt_cici #(
122	    .gp_interpolation_factor (`P_INTERPOLATION),  
123	    .gp_order		     (`P_ORDER),
124	    .gp_diff_delay	     (`P_DIFF_DELAY),
125	    .gp_phase		     (`P_PHASE),
126	    .gp_inp_width	     (`P_INP_DATA_W),
127	    .gp_oup_width	     (`P_OUP_DATA_W)
128	  ) dut (
129	    .i_rst_an (i_rst_an),
130	    .i_ena    (i_ena),
131	    .i_clk    (s_clk),
132	    .i_fclk   (i_fclk),
133	    .i_data   (i_data),
134	    .o_data   (oup_data)
135	  );
136	
137	`ifdef VCD
138	  initial
139	     begin
140	       $sformat(filename_vcd,"%s%0d%s","filt_cici_",`TESTCASE,".vcd");
141	       $dumpfile(filename_vcd);
142	       $dumpvars(0,filt_cici_tb);
143	     end
144	`endif
145	    
146	endmodule
