module shift_register #(
  parameter gp_data_width = 8,                   // Input & output bit-width
  parameter gp_nr_stages  = 4                    // Number of shift registers
) (
  input  wire                     i_rst_an,      // Asynchronous active low reset
  input  wire                     i_ena,         // Synchronous active high enable
  input  wire                     i_clk,         // Rising-edge clock
  input  wire [gp_data_width-1:0] i_data,        // Input data with p_data_width bits MSB:LSB, signed
  output wire [gp_data_width-1:0] o_data,        // Output data with p_data_width bits MSB:LSB, signed
  output wire                     o_shift_done   // Flag indicates inital shift operation is done 
);
// -------------------------------------------------------------------
  // CONSTANT DECLARATION
  localparam c_cnt_width = $clog2(gp_nr_stages);
  // REGISTER DECLARATION
  reg [c_cnt_width-1:0]                 r_cnt;
  reg                                   r_shift_done; 
  // WIRE DECLARATION
  wire                                  w_shift_done;
  wire [gp_nr_stages*gp_data_width-1:0] w_data;
// -------------------------------------------------------------------  
  genvar i;  
  generate
    for (i=0; i<gp_nr_stages; i=i+1)
      begin: g_shift_register
        if (i==0)
          begin: g_shift_register_0
            dff #(
	    .gp_data_width (gp_data_width)
	    ) REG_COMMUTATOR_INP_DATA  (
	    .i_rst_an (i_rst_an),
	    .i_ena    (i_ena),
	    .i_clk    (i_clk),
	    .i_data   (i_data),
	    .o_data   (w_data[(i+1)*gp_data_width-1 -: gp_data_width])
	    );
          end
        else
          begin: g_shift_register_1_n
            dff #(
	    .gp_data_width (gp_data_width)
	    ) REG_COMMUTATOR_INP_DATA  (
	    .i_rst_an (i_rst_an),
	    .i_ena    (i_ena),
	    .i_clk    (i_clk),
	    .i_data   (w_data[(i)*gp_data_width-1 -: gp_data_width]),
	    .o_data   (w_data[(i+1)*gp_data_width-1 -: gp_data_width])
	    );  	  
          end
        end
  endgenerate

  always @(posedge i_clk or negedge i_rst_an)
    begin: p_count_done
      if (!i_rst_an)
        begin
	  r_cnt        <= 'd0;
	  r_shift_done <= 1'b0;
	end
      else if (i_ena)
        begin
	  if (r_cnt<gp_nr_stages)
	    r_cnt <= r_cnt + 1'b1;

	  if (w_shift_done)
	    r_shift_done <= 1'b1;	    
	end
    end

assign w_shift_done = (r_cnt == gp_nr_stages) ? 1'b1 : r_shift_done;
assign o_shift_done = w_shift_done;
assign o_data       = w_data[gp_nr_stages*gp_data_width-1 -: gp_data_width];  

endmodule

function [FilteredData Hcic] = CICFilter(M, N, R, P, Fs, Data, Type)
% [FilteredData Hcic] = CICFilter(M, N, R, Fs, Data)
%
% This function formulate the CIC transfer function, which can be used to
% filter the filter input data and plot the filter response with both input
% and output spectrums. It is integrated with the 
% 'CascadedCICCompensationFilter' function.
%
%   M:              Differntial delay
%   N:              Filter order
%   R:              Decimation factor
%   P:              Downsample phase
%   Fs:             Sampling frequency
%   Data:           Filter input data
%
%   FilteredData:   Filtered and downsampled output data
%   Hcic:           CIC filter transfer function
%
% Ref: GUI Based Decimation Filter Design Toolbox for Multi Standard Wireless Transceveris
%
% Source MSD-Toolbox on MathWorks by Ahmed hahein

Num     = ones(1,R*M);
Den     = 1;
H       = filt(Num,Den,1/Fs);
Hcic    = (H^N);%/((R*M)^N);
Num_CIC = cell2mat(Hcic.num);
Den_CIC = cell2mat(Hcic.den);
if strcmp(Type, 'i') || strcmp(Type, 'I') || strcmp(Type, 'interpolate')
  FilteredData = filter(Num_CIC,Den_CIC,upsample(Data, R, P));disp("### INFO: Interpolation process!");
else
  FilteredData = downsample(filter(Num_CIC,Den_CIC,Data),R, P);
end
